$rawBody=(string)file_get_contents('php://input');if(strlen($rawBody)>2100000)gis_auth_json(413,['ok'=>false,'error'=>'request_body_too_large']);$b=json_decode($rawBody,true);if(!is_array($b))gis_auth_json(400,['ok'=>false,'error'=>'invalid_json']);$pdo=gis_auth_db();$a=(string)($b['action']??'');
if($a==='create_user'){
 $username=strtolower(trim((string)($b['username']??'')));$password=(string)($b['password']??'');$email=trim((string)($b['email']??''));$display=trim((string)($b['display_name']??''));
 if(!preg_match('/^[a-z0-9][a-z0-9._-]{2,63}$/',$username)||strlen($password)<12||strlen($password)>1024||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||strlen($display)>200)gis_auth_json(400,['ok'=>false,'error'=>'invalid_user_parameters']);
 $pdo->beginTransaction();try{$q=$pdo->prepare("INSERT INTO public.gis_users(username,email,password_hash,display_name,status) VALUES(:u,:e,:p,:d,'active') RETURNING id,username,email,display_name,status");$q->execute(['u'=>$username,'e'=>$email!==''?$email:null,'p'=>password_hash($password,PASSWORD_DEFAULT),'d'=>$display]);$new=$q->fetch();$pdo->prepare("INSERT INTO public.gis_admin_audit_log(actor_user_id,action,target_type,target_id,details) VALUES(:a,'create_user','user',:id,CAST(:d AS jsonb))")->execute(['a'=>$u['id'],'id'=>(string)$new['id'],'d'=>json_encode(['username'=>$username])]);$pdo->commit();gis_auth_json(201,['ok'=>true,'user'=>$new]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[gis-auth] create user failed: '.get_class($e));gis_auth_json(409,['ok'=>false,'error'=>'user_creation_failed_or_username_taken']);}
