 if(strlen($name)<2||strlen($name)>200||!preg_match('/^[a-z0-9][a-z0-9-]{1,62}$/',$slug)||!$owner||$owner<1)gis_auth_json(400,['ok'=>false,'error'=>'invalid_organization_parameters']);
 $pdo->beginTransaction();try{$check=$pdo->prepare("SELECT 1 FROM public.gis_users WHERE id=:u AND status='active'");$check->execute(['u'=>$owner]);if(!$check->fetchColumn())throw new OutOfBoundsException('owner_not_active');$q=$pdo->prepare("INSERT INTO public.gis_organizations(name,slug) VALUES(:n,:s) RETURNING id,name,slug,status");$q->execute(['n'=>$name,'s'=>$slug]);$org=$q->fetch();$pdo->prepare("INSERT INTO public.gis_organization_members(organization_id,user_id,role,status) VALUES(:o,:u,'owner','active')")->execute(['o'=>$org['id'],'u'=>$owner]);$pdo->prepare("INSERT INTO public.gis_admin_audit_log(actor_user_id,organization_id,action,target_type,target_id,details) VALUES(:a,:o,'create_organization','organization',:id,CAST(:d AS jsonb))")->execute(['a'=>$u['id'],'o'=>$org['id'],'id'=>(string)$org['id'],'d'=>json_encode(['owner_user_id'=>$owner])]);$pdo->commit();gis_auth_json(201,['ok'=>true,'organization'=>$org]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($e instanceof OutOfBoundsException)gis_auth_json(422,['ok'=>false,'error'=>'owner_must_be_active']);error_log('[gis-auth] create org failed: '.get_class($e));gis_auth_json(409,['ok'=>false,'error'=>'organization_creation_failed']);}
