 if($hasOrg===$hasUser||($hasOrg&&(!$org||$org<1))||($hasUser&&(!$uid||$uid<1))||!preg_match('/^[a-z0-9_-]{2,40}$/',$plan)||!$days||$days<1||$days>3650||!$max||$max<1||$max>10000)gis_auth_json(400,['ok'=>false,'error'=>'invalid_subscription_parameters']);
 $orgVal=$org?:null;$uidVal=$uid?:null;$pdo->beginTransaction();try{$q=$pdo->prepare("INSERT INTO public.gis_subscriptions(organization_id,user_id,plan_code,requested_days,status,starts_at,expires_at,max_users,activated_by,activation_note) VALUES(:o,:u,:p,:days,'pending',NULL,NULL,:m,:a,:n) RETURNING id,organization_id,user_id,plan_code,requested_days,status,max_users");$q->execute(['o'=>$orgVal,'u'=>$uidVal,'p'=>$plan,'days'=>$days,'m'=>$max,'a'=>$u['id'],'n'=>substr(trim((string)($b['note']??'')),0,1000)]);$sub=$q->fetch();$pdo->prepare("INSERT INTO public.gis_admin_audit_log(actor_user_id,organization_id,action,target_type,target_id,details) VALUES(:a,:o,'create_subscription','subscription',:id,CAST(:d AS jsonb))")->execute(['a'=>$u['id'],'o'=>$orgVal,'id'=>(string)$sub['id'],'d'=>json_encode(['user_id'=>$uidVal,'plan_code'=>$plan,'days_requested'=>$days])]);$pdo->commit();gis_auth_json(201,['ok'=>true,'subscription'=>$sub,'requested_days'=>$days]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[gis-auth] create subscription failed: '.get_class($e));gis_auth_json(409,['ok'=>false,'error'=>'subscription_creation_failed']);}
}
if($a==='activate_subscription'){
 $id=filter_var($b['subscription_id']??null,FILTER_VALIDATE_INT);$days=array_key_exists('days',$b)?filter_var($b['days'],FILTER_VALIDATE_INT):null;$note=trim((string)($b['note']??''));if(!$id||$id<1||($days!==null&&($days===false||$days<1||$days>3650))||strlen($note)>1000)gis_auth_json(400,['ok'=>false,'error'=>'invalid_subscription_parameters']);
 $pdo->beginTransaction();try{$q=$pdo->prepare("UPDATE public.gis_subscriptions SET status='active',starts_at=now(),expires_at=now()+make_interval(days => COALESCE(CAST(:days AS integer),requested_days)),activated_by=:actor,activation_note=:note,updated_at=now() WHERE id=:id AND status IN ('pending','expired','suspended') RETURNING id,organization_id,user_id,plan_code,requested_days,status,starts_at,expires_at,max_users");$q->execute(['days'=>$days===false?null:$days,'actor'=>$u['id'],'note'=>$note,'id'=>$id]);$s=$q->fetch();if(!$s){$pdo->rollBack();gis_auth_json(404,['ok'=>false,'error'=>'subscription_not_found_or_not_activatable']);}$pdo->prepare("INSERT INTO public.gis_admin_audit_log(actor_user_id,organization_id,action,target_type,target_id,details) VALUES(:a,:o,'activate_subscription','subscription',:id,CAST(:d AS jsonb))")->execute(['a'=>$u['id'],'o'=>$s['organization_id'],'id'=>(string)$s['id'],'d'=>json_encode(['user_id'=>$s['user_id'],'plan_code'=>$s['plan_code'],'days'=>$s['requested_days'],'note'=>$note])]);$pdo->commit();gis_auth_json(200,['ok'=>true,'subscription'=>$s]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[gis-auth] activation failed: '.get_class($e));gis_auth_json(500,['ok'=>false,'error'=>'subscription_activation_failed']);}
}
